'use strict';

var wrap = require( './../lib' );

var txt = 'Beep boop foo bar.';
var out = wrap( txt );
console.log( out+'\n' );

txt = 'Rounds each element in a single-precision floating-point strided array `x` toward zero and assigns the results to elements in a single-precision floating-point strided array `y`.';
out = wrap( txt );
console.log( out+'\n' );

txt = 'Rounds each element in a single-precision floating-point strided array `x` toward positive infinity and assigns the results to elements in a single-precision floating-point strided array `y`.';
out = wrap( txt );
console.log( out+'\n' );

txt = 'Evaluates the ramp function for each element in a double-precision floating-point strided array `x` and assigns the results to elements in a double-precision floating-point strided array `y`.';
out = wrap( txt );
console.log( out+'\n' );

txt = [
	'Generates a double-precision floating-point Vandermonde matrix.',
	'',
	'When the mode is positive, the matrix is generated such that',
	'',
	'    [',
	'        1   x_0^1   x_0^2   ...   x_0^(N-1)',
	'        1   x_1^1   x_1^2   ...   x_1^(N-1)',
	'        ...',
	'    ]',
	'',
	'with increasing powers along the rows.'
].join( '\n' );
out = wrap( txt );
console.log( out+'\n' );

txt = [
	'Initializes a single-precision floating-point workspace array for performing a real-valued Fourier transform.',
	'',
	'The workspace array is divided into three sections:',
	'',
	'1. scratch/workspace: the section ranges from indices 0 to N-1 and is used while performing transforms. This section is not updated during initialization.',
	'',
	'2. twiddle factors: the section ranges from indices N to 2N-1 and stores a table of reusable complex exponential constants as cosine/sine pairs.'
].join( '\n' );
out = wrap( txt );
console.log( out+'\n' );

txt = [
	'Converts an array to an object supporting fancy indexing.',
	'',
	'Fancy arrays support broadcasting in which assigned scalars and single-element arrays are repeated (without additional memory allocation) to match the length of a target array instance.'
].join( '\n' );
out = wrap( txt );
console.log( out+'\n' );

txt = [
	'In octal representation, a mask is a four digit number, e.g., 0077, comprised as follows:',
	'',
	'- 0: special permissions (setuid, setgid, sticky bit)',
	'- 0: (u)ser/owner permissions',
	'- 7: (g)roup permissions',
	'- 7: (o)thers/non-group permissions',
	'',
	'Permissions can be represented using the following symbolic form:',
	'',
	'    u=rwx,g=rwx,o=rwx'
].join( '\n' );
out = wrap( txt );
console.log( out+'\n' );

txt = [
	'Applies a real elementary reflector `H = I - tau * v * v^T` to a real M by N matrix `C`.',
	'',
	'If `side = \'left\'`,',
	'',
	'- `work` should have `N` indexed elements.',
	'- `V` should have `1 + (M-1) * abs(strideV)` indexed elements.',
	'- `C` is overwritten by `H * C`.',
	'',
	'If `side = \'right\'`,',
	'',
	'- `work` should have `M` indexed elements.',
	'- `V` should have `1 + (N-1) * abs(strideV)` indexed elements.',
	'- `C` is overwritten by `C * H`.'
].join( '\n' );
out = wrap( txt );
console.log( out+'\n' );
